mapper.select:
SELECT 
FROM public.knowledge_items i
WHERE code = #{code}
  AND valid_from <= #{asOf}
  AND (valid_to IS NULL OR valid_to > #{asOf})
  AND EXISTS (
    SELECT 1
    FROM public.knowledge_item_projects access
    JOIN public.user_project_memberships membership
      ON membership.project_code = access.project_code
    JOIN public.projects project ON project.code = membership.project_code
    WHERE access.item_code = i.code
      AND membership.subject = #{subject}
      AND project.active

      AND access.project_code = #{projectCode}

  )

SELECT 
FROM public.knowledge_items i
WHERE valid_from <= #{asOf}
  AND (valid_to IS NULL OR valid_to > #{asOf})
  AND EXISTS (
    SELECT 1
    FROM public.knowledge_item_projects access
    JOIN public.user_project_memberships membership
      ON membership.project_code = access.project_code
    JOIN public.projects project ON project.code = membership.project_code
    WHERE access.item_code = i.code
      AND membership.subject = #{subject}
      AND project.active

      AND access.project_code = #{projectCode}

  )

  AND (title &@ #{query} OR content &@ #{query} OR aliases &@ #{query} OR code = upper(#{query}))


  AND kind = #{kind}


  AND region IN (#{region}, '全国')


  AND status = #{status}

ORDER BY
  CASE WHEN code = upper(#{query}) THEN 0 ELSE 1 END,
  kind, code
LIMIT #{limit}

WITH RECURSIVE graph AS ( SELECT 1 AS depth, #{code}::varchar AS from_code, CASE WHEN r.source_code = #{code} THEN r.relation ELSE 'INVERSE_' || r.relation END AS relation, CASE WHEN r.source_code = #{code} THEN r.target_code ELSE r.source_code END AS to_code, r.rationale, ARRAY[#{code}::varchar, CASE WHEN r.source_code = #{code} THEN r.target_code ELSE r.source_code END]::varchar[] AS path FROM public.knowledge_relations r WHERE (r.source_code = #{code} OR r.target_code = #{code}) AND EXISTS ( SELECT 1 FROM public.knowledge_item_projects start_access JOIN public.user_project_memberships start_membership ON start_membership.project_code = start_access.project_code JOIN public.projects start_project ON start_project.code = start_membership.project_code WHERE start_access.item_code = #{code} AND start_membership.subject = #{subject} AND start_project.active
AND start_access.project_code = #{projectCode}
) AND EXISTS ( SELECT 1 FROM public.knowledge_item_projects next_access JOIN public.user_project_memberships next_membership ON next_membership.project_code = next_access.project_code JOIN public.projects next_project ON next_project.code = next_membership.project_code WHERE next_access.item_code = CASE WHEN r.source_code = #{code} THEN r.target_code ELSE r.source_code END AND next_membership.subject = #{subject} AND next_project.active
AND next_access.project_code = #{projectCode}
) UNION ALL SELECT g.depth + 1, g.to_code, CASE WHEN r.source_code = g.to_code THEN r.relation ELSE 'INVERSE_' || r.relation END, CASE WHEN r.source_code = g.to_code THEN r.target_code ELSE r.source_code END, r.rationale, g.path || CASE WHEN r.source_code = g.to_code THEN r.target_code ELSE r.source_code END FROM graph g JOIN public.knowledge_relations r ON (r.source_code = g.to_code OR r.target_code = g.to_code) WHERE g.depth < #{depth} AND NOT (CASE WHEN r.source_code = g.to_code THEN r.target_code ELSE r.source_code END = ANY(g.path)) AND EXISTS ( SELECT 1 FROM public.knowledge_item_projects next_access JOIN public.user_project_memberships next_membership ON next_membership.project_code = next_access.project_code JOIN public.projects next_project ON next_project.code = next_membership.project_code WHERE next_access.item_code = CASE WHEN r.source_code = g.to_code THEN r.target_code ELSE r.source_code END AND next_membership.subject = #{subject} AND next_project.active
AND next_access.project_code = #{projectCode}
) ) SELECT g.depth, g.from_code, g.relation, g.to_code, g.rationale, i.title, i.kind FROM graph g JOIN public.knowledge_items i ON i.code = g.to_code WHERE i.valid_from <= #{asOf} AND (i.valid_to IS NULL OR i.valid_to > #{asOf}) ORDER BY g.depth, g.relation, g.to_code LIMIT #{limit}
